{"command":"cat <<'EOF' > src/value.rs
use chrono::{DateTime, Utc};
use serde::{Serialize, Serializer};
use std::collections::BTreeMap;
use std::fmt;

#[derive(Debug, Clone, PartialEq, PartialOrd)]
pub enum Value {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Array(Vec<Value>),
    Obj(BTreeMap<String, Value>),
    DateTime(DateTime<Utc>),
}

impl Serialize for Value {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        match self {
            Value::Null => serializer.serialize_none(),
            Value::Bool(b) => serializer.serialize_bool(*b),
            Value::Num(n) => {
                if n.fract() == 0.0 && n.abs() <= i64::MAX as f64 {
                    serializer.serialize_i64(*n as i64)
                } else {
                    serializer.serialize_f64(*n)
                }
            }
            Value::Str(s) => serializer.serialize_str(s),
            Value::Array(arr) => arr.serialize(serializer),
            Value::Obj(map) => map.serialize(serializer),
            Value::DateTime(dt) => serializer.serialize_str(&dt.to_rfc3339()),
        }
    }
}

impl Value {
    pub fn from_json(v: &serde_json::Value) -> Self {
        match v {
            serde_json::Value::Null => Value::Null,
            serde_json::Value::Bool(b) => Value::Bool(*b),
            serde_json::Value::Number(n) => Value::Num(n.as_f64().unwrap_or(0.0)),
            serde_json::Value::String(s) => Value::Str(s.clone()),
            serde_json::Value::Array(arr) => Value::Array(arr.iter().map(Value::from_json).collect()),
            serde_json::Value::Object(map) => {
                let mut bmap = BTreeMap::new();
                for (k, v) in map {
                    bmap.insert(k.clone(), Value::from_json(v));
                }
                Value::Obj(bmap)
            }
        }
    }

    pub fn to_json(&self) -> serde_json::Value {
        match self {
            Value::Null => serde_json::Value::Null,
            Value::Bool(b) => serde_json::Value::Bool(*b),
            Value::Num(n) => {
                if let Some(num) = serde_json::Number::from_f64(*n) {
                    serde_json::Value::Number(num)
                } else {
                    serde_json::Value::Null
                }
            }
            Value::Str(s) => serde_json::Value::String(s.clone()),
            Value::Array(arr) => serde_json::Value::Array(arr.iter().map(|x| x.to_json()).collect()),
            Value::Obj(map) => {
                let mut obj = serde_json::Map::new();
                for (k, v) in map {
                    obj.insert(k.clone(), v.to_json());
                }
                serde_json::Value::Object(obj)
            }
            Value::DateTime(dt) => serde_json::Value::String(dt.to_rfc3339()),
        }
    }

    pub fn as_f64(&self) -> Option<f64> {
        match self {
            Value::Num(n) => Some(*n),
            Value::Str(s) => s.parse::<f64>().ok(),
            Value::Bool(b) => Some(if *b { 1.0 } else { 0.0 }),
            _ => None,
        }
    }

    pub fn as_bool(&self) -> bool {
        match self {
            Value::Bool(b) => *b,
            Value::Num(n) => *n != 0.0,
            Value::Str(s) => !s.is_empty() && s != "false",
            Value::Null => false,
            _ => true,
        }
    }

    pub fn to_legacy_string(&self) -> String {
        match self {
            Value::Null => "None".to_string(),
            Value::Bool(b) => b.to_string(),
            Value::Num(n) => {
                if n.fract() == 0.0 && n.abs() < 1e15 {
                    format!("{:.0}", n)
                } else {
                    format!("{:.2}", n)
                }
            }
            Value::Str(s) => s.clone(),
            Value::Array(arr) => {
                let elems: Vec<String> = arr.iter().map(|e| e.to_legacy_string()).collect();
                format!("[{}]", elems.join(", "))
            }
            Value::Obj(map) => {
                let elems: Vec<String> = map
                    .iter()
                    .map(|(k, v)| format!("{}:{}", k, v.to_legacy_string()))
                    .collect();
                format!("{{{}}}", elems.join(", "))
            }
            Value::DateTime(dt) => dt.format("%Y-%m-%d %H:%M:%S UTC").to_string(),
        }
    }

    pub fn to_table_string(&self) -> String {
        match self {
            Value::Null => "None".to_string(),
            Value::Bool(b) => b.to_string(),
            Value::Num(n) => {
                if n.fract() == 0.0 && n.abs() < 1e15 {
                    format!("{:.0}", n)
                } else {
                    format!("{:.2}", n)
                }
            }
            Value::Str(s) => s.clone(),
            Value::Array(arr) => {
                let elems: Vec<String> = arr.iter().map(|e| e.to_table_string()).collect();
                format!("[{}]", elems.join(", "))
            }
            Value::Obj(map) => {
                let elems: Vec<String> = map
                    .iter()
                    .map(|(k, v)| format!("{}:{}", k, v.to_table_string()))
                    .collect();
                format!("{{{}}}", elems.join(", "))
            }
            Value::DateTime(dt) => dt.format("%Y-%m-%d %H:%M:%S UTC").to_string(),
        }
    }
}

impl fmt::Display for Value {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.to_legacy_string())
    }
}
EOF"}

