{"command":"cat <<'EOF' > src/record.rs
use crate::value::Value;
use std::collections::BTreeMap;

#[derive(Debug, Clone, PartialEq)]
pub struct Record {
    pub fields: Vec<(String, Value)>,
}

impl Record {
    pub fn new() -> Self {
        Record { fields: Vec::new() }
    }

    pub fn from_raw(raw: String) -> Self {
        let mut rec = Record::new();
        rec.set("_raw", Value::Str(raw));
        rec
    }

    pub fn get(&self, key: &str) -> Option<&Value> {
        for (k, v) in &self.fields {
            if k == key {
                return Some(v);
            }
        }
        None
    }

    pub fn set(&mut self, key: impl Into<String>, val: Value) {
        let key_str = key.into();
        for (k, v) in &mut self.fields {
            if k == &key_str {
                *v = val;
                return;
            }
        }
        self.fields.push((key_str, val));
    }

    pub fn remove(&mut self, key: &str) {
        self.fields.retain(|(k, _)| k != key);
    }

    pub fn clear(&mut self) {
        self.fields.clear();
    }

    pub fn get_path(&self, path: &str) -> Result<Value, String> {
        // Handle escaped field names like ["foo.bar"]
        let path = path.trim();
        if path.starts_with("[\"") && path.ends_with("\"]") {
            let inner = &path[2..path.len() - 2];
            return self
                .get(inner)
                .cloned()
                .ok_or_else(|| format!("No value for key \"{}\"", inner));
        }

        // Parse path into segments: e.g. a.b[0] -> root "a", navigation steps ".b", "[0]"
        let mut root_key = String::new();
        let mut idx = 0;
        let bytes = path.as_bytes();

        while idx < bytes.len() {
            let ch = bytes[idx] as char;
            if ch == '.' || ch == '[' {
                break;
            }
            root_key.push(ch);
            idx += 1;
        }

        if root_key.is_empty() {
            return Err(format!("Invalid path \"{}\"", path));
        }

        let mut curr = match self.get(&root_key) {
            Some(v) => v.clone(),
            None => return Err(format!("No value for key \"{}\"", root_key)),
        };

        while idx < bytes.len() {
            if bytes[idx] as char == '.' {
                idx += 1;
                let mut subkey = String::new();
                while idx < bytes.len() {
                    let ch = bytes[idx] as char;
                    if ch == '.' || ch == '[' {
                        break;
                    }
                    subkey.push(ch);
                    idx += 1;
                }
                match curr {
                    Value::Obj(map) => match map.get(&subkey) {
                        Some(v) => curr = v.clone(),
                        None => return Err(format!("No value for key \"{}\"", subkey)),
                    },
                    _ => return Err(format!("Key \"{}\" is not an object", subkey)),
                }
            } else if bytes[idx] as char == '[' {
                idx += 1;
                let mut index_str = String::new();
                while idx < bytes.len() && bytes[idx] as char != ']' {
                    index_str.push(bytes[idx] as char);
                    idx += 1;
                }
                if idx < bytes.len() && bytes[idx] as char == ']' {
                    idx += 1;
                }
                let i: i64 = index_str
                    .parse()
                    .map_err(|_| format!("Invalid index \"{}\"", index_str))?;
                match curr {
                    Value::Array(arr) => {
                        let len = arr.len() as i64;
                        let actual_idx = if i >= 0 { i } else { len + i };
                        if actual_idx < 0 || actual_idx >= len {
                            return Err(format!("Index {} out of range", i));
                        }
                        curr = arr[actual_idx as usize].clone();
                    }
                    _ => return Err(format!("Value is not an array for index [{}]", i)),
                }
            } else {
                idx += 1;
            }
        }

        Ok(curr)
    }

    pub fn to_json_object(&self) -> serde_json::Value {
        let mut map = serde_json::Map::new();
        for (k, v) in &self.fields {
            map.insert(k.clone(), v.to_json());
        }
        serde_json::Value::Object(map)
    }
}
EOF"}

