{"command":"cat <<'EOF' > src/alias.rs
use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};

pub struct AliasManager {
    aliases: HashMap<String, String>,
}

impl AliasManager {
    pub fn load(alias_dir: Option<&Path>, no_alias: bool) -> Result<Self, String> {
        let mut map = HashMap::new();
        if no_alias {
            return Ok(AliasManager { aliases: map });
        }

        if let Some(dir) = alias_dir {
            if !dir.exists() {
                return Err(format!("Error: No such file or directory (os error 2)"));
            }
            Self::load_dir(dir, &mut map)?;
        } else {
            // Find all .agrind-aliases directories from current directory up to root
            if let Ok(mut current) = std::env::current_dir() {
                loop {
                    let alias_path = current.join(".agrind-aliases");
                    if alias_path.is_dir() {
                        let _ = Self::load_dir(&alias_path, &mut map);
                    }
                    if !current.pop() {
                        break;
                    }
                }
            }
        }

        Ok(AliasManager { aliases: map })
    }

    fn load_dir(dir: &Path, map: &mut HashMap<String, String>) -> Result<(), String> {
        let entries = match fs::read_dir(dir) {
            Ok(e) => e,
            Err(err) => return Err(format!("Error: {}", err)),
        };

        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_file() && path.extension().and_then(|s| s.to_str()) == Some("toml") {
                if let Ok(content) = fs::read_to_string(&path) {
                    match toml::from_str::<toml::Value>(&content) {
                        Ok(toml_val) => {
                            if let (Some(kw), Some(tmpl)) = (
                                toml_val.get("keyword").and_then(|v| v.as_str()),
                                toml_val.get("template").and_then(|v| v.as_str()),
                            ) {
                                map.insert(kw.to_string(), tmpl.to_string());
                            }
                        }
                        Err(err) => {
                            eprintln!(
                                "warning: invalid alias: {}\n  --> {}",
                                err,
                                path.display()
                            );
                        }
                    }
                }
            }
        }

        Ok(())
    }

    pub fn expand(&self, query: &str) -> String {
        // Expand any alias keyword in query stages
        let stages: Vec<&str> = query.split('|').collect();
        let mut expanded_stages = Vec::new();

        for (i, stage) in stages.iter().enumerate() {
            let trimmed = stage.trim();
            if i > 0 {
                // Check if stage starts with an alias keyword
                let word = trimmed.split_whitespace().next().unwrap_or("");
                if let Some(tmpl) = self.aliases.get(word) {
                    let rest = &trimmed[word.len()..];
                    expanded_stages.push(format!("{}{}", tmpl.trim(), rest));
                    continue;
                }
            }
            expanded_stages.push(trimmed.to_string());
        }

        expanded_stages.join(" | ")
    }
}
EOF"}

