use regex::{Regex, RegexBuilder};

#[derive(Debug, Clone, PartialEq)]
pub enum Filter {
    Star,
    Exact(String),
    Glob(String),
    And(Vec<Filter>),
    Or(Vec<Filter>),
    Not(Box<Filter>),
}

impl Filter {
    pub fn matches(&self, line: &str) -> bool {
        match self {
            Filter::Star => true,
            Filter::Exact(pat) => line.contains(pat),
            Filter::Glob(pat) => {
                let mut regex_str = "^.*".to_string();
                for part in pat.split('*') {
                    regex_str.push_str(&regex::escape(part));
                    regex_str.push_str(".*");
                }
                regex_str.push('$');
                if let Ok(re) = RegexBuilder::new(&regex_str).case_insensitive(true).build() {
                    re.is_match(line)
                } else {
                    false
                }
            }
            Filter::And(filters) => filters.iter().all(|f| f.matches(line)),
            Filter::Or(filters) => filters.iter().any(|f| f.matches(line)),
            Filter::Not(filter) => !filter.matches(line),
        }
    }
}
EOF"}

