pub fn parse_filter(input: &str) -> Result<Filter, String> {
    let s = input.trim();
    if s == "*" || s.is_empty() {
        return Ok(Filter::Star);
    }

    // Check parenthesized expressions e.g. (foo OR bar) AND NOT baz
    let tokens = tokenize(s);
    parse_filter_expr(&tokens)
}

fn parse_filter_expr(tokens: &[String]) -> Result<Filter, String> {
