            filters.push(parse_filter_and(&part)?);
        }
        return Ok(Filter::Or(filters));
    }

    parse_filter_and(tokens)
}

fn parse_filter_and(tokens: &[String]) -> Result<Filter, String> {
    let mut and_parts = Vec::new();
    let mut current_part = Vec::new();
    let mut paren_depth = 0;

    for tok in tokens {
        if tok == "(" {
            paren_depth += 1;
            current_part.push(tok.clone());
        } else if tok == ")" {
            paren_depth -= 1;
            current_part.push(tok.clone());
        } else if tok.eq_ignore_ascii_case("AND") && paren_depth == 0 {
            and_parts.push(current_part.clone());
            current_part.clear();
        } else {
            current_part.push(tok.clone());
        }
    }
    and_parts.push(current_part);

    if and_parts.len() > 1 {
        let mut filters = Vec::new();
        for part in and_parts {
            filters.push(parse_filter_atom(&part)?);
        }
        return Ok(Filter::And(filters));
    }

    parse_filter_atom(tokens)
}

fn parse_filter_atom(tokens: &[String]) -> Result<Filter, String> {
    if tokens.is_empty() {
        return Ok(Filter::Star);
    }

    if tokens[0].eq_ignore_ascii_case("NOT") || tokens[0] == "!" {
        let inner = parse_filter_atom(&tokens[1..])?;
        return Ok(Filter::Not(Box::new(inner)));
    }

    if tokens.len() == 1 {
        let t = &tokens[0];
        if t == "*" {
            return Ok(Filter::Star);
        }
        if t.starts_with('"') && t.ends_with('"') && t.len() >= 2 {
            let inner = &t[1..t.len() - 1];
            return Ok(Filter::Exact(inner.to_string()));
        }
        return Ok(Filter::Glob(t.to_string()));
    }

    if tokens.first() == Some(&"(".to_string()) && tokens.last() == Some(&")".to_string()) {
        return parse_filter_expr(&tokens[1..tokens.len() - 1]);
    }

    // Implicit AND for adjacent tokens
    let mut filters = Vec::new();
    let mut i = 0;
    while i < tokens.len() {
        if tokens[i] == "(" {
            let mut depth = 1;
            let start = i + 1;
            i += 1;
            while i < tokens.len() && depth > 0 {
                if tokens[i] == "(" {
                    depth += 1;
                } else if tokens[i] == ")" {
                    depth -= 1;
                }
                i += 1;
            }
            if depth != 0 {
                return Err(format!(
                    "error: unterminated parenthesized filter\n  |\n1 | {}\n",
                    tokens.join(" ")
                ));
            }
            let sub_f = parse_filter_expr(&tokens[start..i - 1])?;
            filters.push(sub_f);
        } else {
            let sub_f = parse_filter_atom(&[tokens[i].clone()])?;
            filters.push(sub_f);
            i += 1;
        }
    }

    if filters.len() == 1 {
        Ok(filters.remove(0))
    } else {
        Ok(Filter::And(filters))
    }
}

pub fn tokenize(s: &str) -> Vec<String> {
    let mut tokens = Vec::new();
    let mut curr = String::new();
    let mut in_quote = false;

    for ch in s.chars() {
        if ch == '"' {
            in_quote = !in_quote;
            curr.push(ch);
        } else if in_quote {
            curr.push(ch);
        } else if ch == '(' || ch == ')' {
            if !curr.trim().is_empty() {
                tokens.push(curr.trim().to_string());
                curr.clear();
            }
            tokens.push(ch.to_string());
        } else if ch.is_whitespace() {
            if !curr.trim().is_empty() {
                tokens.push(curr.trim().to_string());
                curr.clear();
            }
        } else {
            curr.push(ch);
        }
    }
    if !curr.trim().is_empty() {
        tokens.push(curr.trim().to_string());
    }
    tokens
}

fn parse_operator(input: &str) -> Result<Operator, String> {
    let s = input.trim();
    let first_word = s.split_whitespace().next().unwrap_or("");

    match first_word {
        "json" => {
            let rest = s["json".len()..].trim();
            let from = if rest.starts_with("from ") {
                Some(rest["from ".len()..].trim().to_string())
            } else {
                None
            };
            Ok(Operator::Json { from })
        }
        "logfmt" => {
            let rest = s["logfmt".len()..].trim();
            let from = if rest.starts_with("from ") {
                Some(rest["from ".len()..].trim().to_string())
            } else {
                None
            };
            Ok(Operator::Logfmt { from })
        }
        "split" => parse_split_op(s),
        "parse" => {
            if s.starts_with("parse regex") {
                parse_parse_regex_op(s)
            } else {
                parse_parse_op(s)
            }
        }
        "fields" => parse_fields_op(s),
        "where" => {
            let expr_str = s["where".len()..].trim();
            let expr = parse_expr(expr_str)?;
            Ok(Operator::Where { expr })
        }
        "limit" => {
            let count_str = s["limit".len()..].trim();
            let count: i64 = count_str
                .parse()
                .map_err(|_| format!("Invalid limit count: {}", count_str))?;
            Ok(Operator::Limit { count })
        }
        "timeslice" => parse_timeslice_op(s),
        "total" => parse_total_op(s),
        "sort" => parse_sort_op(s),
        _ => {
            if is_aggregate_op(s) {
                parse_aggregate_op(s)
            } else if s.contains(" as ") {
                parse_assignment_op(s)
            } else {
                Err(format!(
                    "error: Expected an operator\n  |\n1 | {}\n  |\n  = help: {} is not a valid operator",
                    s, first_word
                ))
            }
        }
    }
}

fn parse_split_op(s: &str) -> Result<Operator, String> {
    // split[(field)] [on "sep"] [as new_field]
    let rest = s["split".len()..].trim();
    let mut field = None;
    let mut on = None;
    let mut as_name = None;

    let mut remaining = rest;
    if remaining.starts_with('(') {
        if let Some(close_idx) = remaining.find(')') {
            let f = remaining[1..close_idx].trim().to_string();
            if !f.is_empty() {
                field = Some(f);
            }
            remaining = remaining[close_idx + 1..].trim();
        }
    }

    if let Some(on_idx) = remaining.find("on ") {
        let after_on = remaining[on_idx + "on ".len()..].trim();
        let sep_str = if after_on.starts_with('"') {
            let end_q = after_on[1..].find('"').unwrap_or(after_on.len() - 1);
            after_on[1..end_q + 1].to_string()
        } else {
            after_on.split_whitespace().next().unwrap_or(",").to_string()
        };
        on = Some(sep_str);
    }

    if let Some(as_idx) = remaining.find(" as ") {
        let name = remaining[as_idx + " as ".len()..].trim().to_string();
        if !name.is_empty() {
            as_name = Some(name);
        }
    }

    Ok(Operator::Split { field, on, as_name })
}

fn parse_parse_op(s: &str) -> Result<Operator, String> {
    let rest = s["parse".len()..].trim();
    let nodrop = rest.contains("nodrop");
    let noconvert = rest.contains("noconvert");

    let first_quote = rest.find('"').ok_or_else(|| "Missing pattern quote in parse".to_string())?;
    let last_quote = rest[first_quote + 1..].find('"').ok_or_else(|| "Missing closing quote in parse".to_string())? + first_quote + 1;
    let pattern = rest[first_quote + 1..last_quote].to_string();

    let after_pattern = rest[last_quote + 1..].trim();
    let from = if let Some(from_idx) = after_pattern.find("from ") {
        let after_from = after_pattern[from_idx + "from ".len()..].trim();
        let f = after_from.split_whitespace().next().unwrap_or("").to_string();
        if !f.is_empty() { Some(f) } else { None }
    } else {
        None
    };

    let mut vars = Vec::new();
    if let Some(as_idx) = after_pattern.find("as ") {
        let after_as = after_pattern[as_idx + "as ".len()..].trim();
        let end_vars = after_as
            .find("nodrop")
            .or_else(|| after_as.find("noconvert"))
            .unwrap_or(after_as.len());
        let var_str = after_as[..end_vars].trim();
        for v in var_str.split(',') {
            let name = v.trim().to_string();
            if !name.is_empty() {
                vars.push(name);
            }
        }
    }

    Ok(Operator::Parse {
        pattern,
        from,
        vars,
        nodrop,
        noconvert,
    })
}

fn parse_parse_regex_op(s: &str) -> Result<Operator, String> {
    let rest = s["parse regex".len()..].trim();
    let nodrop = rest.contains("nodrop");

    let first_quote = rest.find('"').ok_or_else(|| "Missing regex quote".to_string())?;
    let last_quote = rest[first_quote + 1..].find('"').ok_or_else(|| "Missing closing regex quote".to_string())? + first_quote + 1;
    let regex_str = rest[first_quote + 1..last_quote].to_string();

    // Check for unnamed captures
    if let Ok(re) = regex::Regex::new(&regex_str) {
        let captures_count = re.captures_len() - 1;
        let named_count = re.capture_names().flatten().count();
        if captures_count > named_count {
            return Err(format!(
                "error: regular expression for the parse operator cannot have unnamed captures\n  |\n1 | {}\n  | contains {} unnamed capture(s)\n  = help: name the capture groups by adding -- ?P<capname> -- right after the left parenthesis",
                s, captures_count - named_count
            ));
        }
    }

    let after_quote = rest[last_quote + 1..].trim();
    let from = if let Some(from_idx) = after_quote.find("from ") {
        let after_from = after_quote[from_idx + "from ".len()..].trim();
        let f = after_from.split_whitespace().next().unwrap_or("").to_string();
        if !f.is_empty() { Some(f) } else { None }
    } else {
        None
    };

    Ok(Operator::ParseRegex {
        regex: regex_str,
        from,
        nodrop,
    })
}

fn parse_fields_op(s: &str) -> Result<Operator, String> {
    let rest = s["fields".len()..].trim();
    let mode = if rest.starts_with("except") || rest.starts_with('-') {
        FieldsMode::Except
    } else {
        FieldsMode::Only
    };

    let clean = rest
        .trim_start_matches("only")
        .trim_start_matches("except")
        .trim_start_matches('+')
        .trim_start_matches('-')
        .trim();

    let fields = clean
        .split(',')
        .map(|f| f.trim().to_string())
        .filter(|f| !f.is_empty())
        .collect();

    Ok(Operator::Fields { mode, fields })
}

fn parse_timeslice_op(s: &str) -> Result<Operator, String> {
    let rest = s["timeslice".len()..].trim();
    let open_p = rest.find('(').ok_or_else(|| "timeslice missing '('".to_string())?;
    let close_p = rest.find(')').ok_or_else(|| "timeslice missing ')'".to_string())?;
    let expr_str = rest[open_p + 1..close_p].trim();
    let expr = parse_expr(expr_str)?;

    let after = rest[close_p + 1..].trim();
    let mut parts = after.split_whitespace();
    let duration = parts.next().unwrap_or("1m").to_string();

    let as_name = if after.contains(" as ") {
        let idx = after.find(" as ").unwrap();
        Some(after[idx + " as ".len()..].trim().to_string())
    } else {
        None
    };

    Ok(Operator::Timeslice {
        expr,
        duration,
        as_name,
    })
}

fn parse_total_op(s: &str) -> Result<Operator, String> {
    let rest = s["total".len()..].trim();
    let open_p = rest.find('(').ok_or_else(|| "total missing '('".to_string())?;
    let close_p = rest.find(')').ok_or_else(|| "total missing ')'".to_string())?;
    let expr_str = rest[open_p + 1..close_p].trim();
    let expr = parse_expr(expr_str)?;

    let after = rest[close_p + 1..].trim();
    let as_name = if after.starts_with("as ") {
        Some(after["as ".len()..].trim().to_string())
    } else {
        None
    };

    Ok(Operator::Total { expr, as_name })
}

fn parse_assignment_op(s: &str) -> Result<Operator, String> {
    let as_idx = s.rfind(" as ").ok_or_else(|| "Missing 'as'".to_string())?;
    let expr_str = s[..as_idx].trim();
    let name = s[as_idx + " as ".len()..].trim().to_string();
    let expr = parse_expr(expr_str)?;
    Ok(Operator::Assignment { expr, name })
}

fn is_aggregate_op(s: &str) -> bool {
    let s = s.trim();
    s.starts_with("count")
        || s.starts_with("sum")
        || s.starts_with("min")
        || s.starts_with("max")
        || s.starts_with("avg")
        || s.starts_with("average")
        || s.starts_with("p") && s.chars().nth(1).map_or(false, |c| c.is_ascii_digit())
        || s.starts_with("pct")
        || s.starts_with("count_distinct")
        || s.starts_with("countDistinct")
}

fn parse_aggregate_op(s: &str) -> Result<Operator, String> {
    let (funcs_part, by_part) = if let Some(by_idx) = s.find(" by ") {
        (&s[..by_idx], Some(&s[by_idx + " by ".len()..]))
    } else {
        (s, None)
    };

    let mut funcs = Vec::new();
    let raw_funcs = split_commas(funcs_part);

    for f_str in raw_funcs {
        let f_str = f_str.trim();
        if f_str.is_empty() {
            continue;
        }

        let as_name = if let Some(as_idx) = f_str.rfind(" as ") {
            Some(f_str[as_idx + " as ".len()..].trim().to_string())
        } else {
            None
        };
        let core = if let Some(as_idx) = f_str.rfind(" as ") {
            f_str[..as_idx].trim()
        } else {
            f_str
        };

        if core == "count" {
            funcs.push(AggFunc::Count { cond: None, as_name });
        } else if core.starts_with("count(") && core.ends_with(')') {
            let inner = core["count(".len()..core.len() - 1].trim();
            let cond = if inner.is_empty() { None } else { Some(parse_expr(inner)?) };
            funcs.push(AggFunc::Count { cond, as_name });
        } else if core.starts_with("sum(") && core.ends_with(')') {
            let inner = core["sum(".len()..core.len() - 1].trim();
            funcs.push(AggFunc::Sum { expr: parse_expr(inner)?, as_name });
        } else if core.starts_with("min(") && core.ends_with(')') {
            let inner = core["min(".len()..core.len() - 1].trim();
            funcs.push(AggFunc::Min { expr: parse_expr(inner)?, as_name });
        } else if core.starts_with("max(") && core.ends_with(')') {
            let inner = core["max(".len()..core.len() - 1].trim();
            funcs.push(AggFunc::Max { expr: parse_expr(inner)?, as_name });
        } else if (core.starts_with("avg(") || core.starts_with("average(")) && core.ends_with(')') {
            let open = core.find('(').unwrap();
            let inner = core[open + 1..core.len() - 1].trim();
            funcs.push(AggFunc::Average { expr: parse_expr(inner)?, as_name });
        } else if core.starts_with('p') || core.starts_with("pct") {
            let open = core.find('(').ok_or_else(|| format!("Invalid percentile syntax {}", core))?;
            let pct_str = if core.starts_with("pct") {
                &core["pct".len()..open]
            } else {
                &core[1..open]
            };
            let pct: usize = pct_str.parse().map_err(|_| format!("invalid percentile number: {}", pct_str))?;
            if pct == 0 || pct >= 100 {
                return Err(format!("invalid percentile number: {}\n  |\n1 | {}\n  | expecting a number between (0, 100)", pct, core));
            }
            let inner = core[open + 1..core.len() - 1].trim();
            funcs.push(AggFunc::Percentile { pct, expr: parse_expr(inner)?, as_name });
        } else if (core.starts_with("count_distinct(") || core.starts_with("countDistinct(")) && core.ends_with(')') {
            let open = core.find('(').unwrap();
            let inner = core[open + 1..core.len() - 1].trim();
            funcs.push(AggFunc::CountDistinct { expr: parse_expr(inner)?, as_name });
        } else {
            return Err(format!("Unknown aggregate function {}", core));
        }
    }

    let mut by = Vec::new();
    if let Some(by_str) = by_part {
        for b_expr_str in split_commas(by_str) {
            let trimmed = b_expr_str.trim();
            if !trimmed.is_empty() {
                by.push(parse_expr(trimmed)?);
            }
        }
    }

    Ok(Operator::Aggregate { funcs, by })
}

fn parse_sort_op(s: &str) -> Result<Operator, String> {
    let rest = s["sort".len()..].trim();
    let body = if rest.starts_with("by ") {
        rest["by ".len()..].trim()
    } else {
        rest
    };

    let dir = if body.ends_with(" desc") {
        SortDir::Desc
    } else {
        SortDir::Asc
    };

    let clean_body = body
        .trim_end_matches(" desc")
        .trim_end_matches(" asc")
        .trim();

    let mut items = Vec::new();
    for part in split_commas(clean_body) {
        let trimmed = part.trim();
        if !trimmed.is_empty() {
            items.push((parse_expr(trimmed)?, dir));
        }
    }

    Ok(Operator::Sort { items })
}

fn split_commas(s: &str) -> Vec<String> {
    let mut res = Vec::new();
    let mut curr = String::new();
    let mut depth = 0;
    let mut in_single = false;
    let mut in_double = false;

    for ch in s.chars() {
        match ch {
            '\'' if !in_double => in_single = !in_single,
            '"' if !in_single => in_double = !in_double,
            '(' if !in_single && !in_double => depth += 1,
            ')' if !in_single && !in_double => depth = depth.saturating_sub(1),
            ',' if !in_single && !in_double && depth == 0 => {
                res.push(curr.clone());
                curr.clear();
                continue;
            }
            _ => {}
        }
        curr.push(ch);
    }
    if !curr.is_empty() {
        res.push(curr);
    }
    res
}

pub fn parse_expr(input: &str) -> Result<Expr, String> {
    let input = input.trim();
    if input.is_empty() {
        return Err("Empty expression".to_string());
    }

    // Binary OR / AND
    if let Some(pos) = find_op(input, &[" or ", " || "]) {
        let op_str = if input[pos..].starts_with(" or ") { " or " } else { " || " };
        let left = parse_expr(&input[..pos])?;
        let right = parse_expr(&input[pos + op_str.len()..])?;
        return Ok(Expr::Binary {
            op: BinaryOp::Or,
            left: Box::new(left),
            right: Box::new(right),
        });
    }

    if let Some(pos) = find_op(input, &[" and ", " && "]) {
        let op_str = if input[pos..].starts_with(" and ") { " and " } else { " && " };
        let left = parse_expr(&input[..pos])?;
        let right = parse_expr(&input[pos + op_str.len()..])?;
        return Ok(Expr::Binary {
            op: BinaryOp::And,
            left: Box::new(left),
            right: Box::new(right),
        });
    }

    // Comparisons: ==, !=, <=, >=, <, >
    if let Some(pos) = find_op(input, &["==", "!=", "<=", ">=", "<", ">"]) {
        let (op, len) = if input[pos..].starts_with("==") {
            (BinaryOp::Eq, 2)
        } else if input[pos..].starts_with("!=") {
            (BinaryOp::Neq, 2)
        } else if input[pos..].starts_with("<=") {
            (BinaryOp::Lte, 2)
        } else if input[pos..].starts_with(">=") {
            (BinaryOp::Gte, 2)
        } else if input[pos..].starts_with("<") {
            (BinaryOp::Lt, 1)
        } else {
            (BinaryOp::Gt, 1)
        };
        let left = parse_expr(&input[..pos])?;
        let right = parse_expr(&input[pos + len..])?;
        return Ok(Expr::Binary {
            op,
            left: Box::new(left),
            right: Box::new(right),
        });
    }

    // Add / Sub
    if let Some(pos) = find_op(input, &["+", "-"]) {
        let ch = &input[pos..pos + 1];
        let op = if ch == "+" { BinaryOp::Add } else { BinaryOp::Sub };
        let left = parse_expr(&input[..pos])?;
        let right = parse_expr(&input[pos + 1..])?;
        return Ok(Expr::Binary {
            op,
            left: Box::new(left),
            right: Box::new(right),
        });
    }

    // Mul / Div
    if let Some(pos) = find_op(input, &["*", "/"]) {
        let ch = &input[pos..pos + 1];
        let op = if ch == "*" { BinaryOp::Mul } else { BinaryOp::Div };
        let left = parse_expr(&input[..pos])?;
        let right = parse_expr(&input[pos + 1..])?;
        return Ok(Expr::Binary {
            op,
            left: Box::new(left),
            right: Box::new(right),
        });
    }

    // Unary ! or not
    if input.starts_with('!') || input.starts_with("not ") {
        let start = if input.starts_with('!') { 1 } else { 4 };
        let inner = parse_expr(&input[start..])?;
        return Ok(Expr::Unary {
            op: UnaryOp::Not,
            expr: Box::new(inner),
        });
    }

    // Unary minus
    if input.starts_with('-') && !input[1..].trim().is_empty() && input[1..].chars().next().unwrap().is_ascii_digit() {
        let inner = parse_expr(&input[1..])?;
        return Ok(Expr::Unary {
            op: UnaryOp::Neg,
            expr: Box::new(inner),
        });
    }

    // Function calls e.g. func(a, b)
    if let Some(open) = input.find('(') {
        if input.ends_with(')') {
            let func_name = input[..open].trim();
            if is_ident(func_name) {
                let args_str = &input[open + 1..input.len() - 1];
                let raw_args = split_commas(args_str);
                let mut args = Vec::new();
                for a_str in raw_args {
                    if !a_str.trim().is_empty() {
                        args.push(parse_expr(a_str.trim())?);
                    }
                }
                return Ok(Expr::Call {
                    name: func_name.to_string(),
                    args,
                });
            }
        }
    }

    // Parenthesized subexpression
    if input.starts_with('(') && input.ends_with(')') {
        return parse_expr(&input[1..input.len() - 1]);
    }

    // Literals
    if input == "true" {
        return Ok(Expr::Lit(Value::Bool(true)));
    }
    if input == "false" {
        return Ok(Expr::Lit(Value::Bool(false)));
    }
    if input == "null" || input == "None" {
        return Ok(Expr::Lit(Value::Null));
    }
    if (input.starts_with('"') && input.ends_with('"')) || (input.starts_with('\'') && input.ends_with('\'')) {
        let inner = &input[1..input.len() - 1];
        return Ok(Expr::Lit(Value::Str(inner.to_string())));
    }
    if let Ok(num) = input.parse::<f64>() {
        return Ok(Expr::Lit(Value::Num(num)));
    }

    // Variable / Field reference
    Ok(Expr::Var(input.to_string()))
}

fn find_op(s: &str, ops: &[&str]) -> Option<usize> {
    let mut depth = 0;
    let mut in_single = false;
    let mut in_double = false;
    let chars: Vec<char> = s.chars().collect();

    for i in (0..chars.len()).rev() {
        let ch = chars[i];
        match ch {
            '\'' if !in_double => in_single = !in_single,
            '"' if !in_single => in_double = !in_double,
            ')' if !in_single && !in_double => depth += 1,
            '(' if !in_single && !in_double => depth = depth.saturating_sub(1),
            _ => {}
        }
        if depth == 0 && !in_single && !in_double {
            for op in ops {
                if s[i..].starts_with(op) {
                    return Some(i);
                }
            }
        }
    }
    None
}

fn is_ident(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }
    let first = s.chars().next().unwrap();
    (first.is_ascii_alphabetic() || first == '_') && s.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
}
EOF"}

