{"command":"cat <<'EOF' > src/render/non_aggregate.rs
use crate::record::Record;
use crate::render::OutputMode;
use crate::value::Value;
use std::collections::HashMap;

pub struct NonAggregateRenderer {
    pub mode: OutputMode,
    pub format_str: Option<String>,
    pub col_widths: HashMap<String, usize>,
    pub col_order: Vec<String>,
}

impl NonAggregateRenderer {
    pub fn new(mode: OutputMode, format_str: Option<String>) -> Self {
        NonAggregateRenderer {
            mode,
            format_str,
            col_widths: HashMap::new(),
            col_order: Vec::new(),
        }
    }

    pub fn render_record(&mut self, record: &Record) {
        match self.mode {
            OutputMode::Legacy => {
                let mut fields = record.fields.clone();
                // Sort fields alphabetically if all new
                fields.sort_by(|a, b| a.0.cmp(&b.0));

                for (k, v) in &fields {
                    if !self.col_order.contains(k) {
                        self.col_order.push(k.clone());
                    }
                    let formatted = format!("[{}={}]", k, v.to_legacy_string());
                    let width = self.col_widths.entry(k.clone()).or_insert(0);
                    *width = (*width).max(formatted.len());
                }

                let mut parts = Vec::new();
                for col in &self.col_order {
                    if let Some(v) = record.get(col) {
                        let cell = format!("[{}={}]", col, v.to_legacy_string());
                        let target_width = *self.col_widths.get(col).unwrap_or(&cell.len());
                        let padding = target_width.saturating_sub(cell.len());
                        parts.push(format!("{}{}", cell, " ".repeat(padding)));
                    }
                }
                println!("{}", parts.join("        "));
            }
            OutputMode::Json => {
                let json_val = record.to_json_object();
                println!("{}", json_val);
            }
            OutputMode::Logfmt => {
                let mut parts = Vec::new();
                for (k, v) in &record.fields {
                    parts.push(format!("{}={}", k, v.to_legacy_string()));
                }
                println!("{}", parts.join(" "));
            }
            OutputMode::Format => {
                if let Some(fmt_str) = &self.format_str {
                    let mut res = fmt_str.clone();
                    for (k, v) in &record.fields {
                        res = res.replace(&format!("{{{}}}", k), &v.to_legacy_string());
                    }
                    // Unreplaced placeholders become "None"
                    while let Some(start) = res.find('{') {
                        if let Some(end) = res[start..].find('}') {
                            let key = &res[start..start + end + 1];
                            res = res.replace(key, "None");
                        } else {
                            break;
                        }
                    }
                    println!("{}", res);
                }
            }
        }
    }
}
EOF"}

