use crate::parser::expr::Expr;
use crate::parser::operator::{FieldsMode, Operator};
use crate::record::Record;
use crate::value::Value;
use chrono::{DateTime, Duration, DurationRound, TimeZone, Utc};
use regex::Regex;
use serde_json::Value as JsonValue;
use std::collections::BTreeMap;

pub fn execute_non_aggregate_operator(
    op: &Operator,
    record: Record,
    running_total: &mut f64,
) -> Option<Record> {
    match op {
        Operator::Json { from } => {
            let input_str = match from {
                Some(f) => match record.get_path(f) {
                    Ok(v) => v.to_legacy_string(),
                    Err(_) => return None,
                },
                None => match record.get("_raw") {
                    Some(Value::Str(s)) => s.clone(),
                    _ => return None,
                },
            };

            let json_val: JsonValue = match serde_json::from_str(&input_str) {
                Ok(v) => v,
                Err(_) => {
                    eprintln!("error: Expected JSON, found {}", input_str);
                    return None;
                }
            };

            let mut rec = Record::new();
            if let JsonValue::Object(map) = json_val {
                let mut sorted_keys: Vec<String> = map.keys().cloned().collect();
                sorted_keys.sort();
                for k in sorted_keys {
                    rec.set(k.clone(), Value::from_json(&map[&k]));
                }
            } else {
                rec.set("_json", Value::from_json(&json_val));
            }
            Some(rec)
        }
        Operator::Logfmt { from } => {
            let input_str = match from {
                Some(f) => match record.get_path(f) {
                    Ok(v) => v.to_legacy_string(),
                    Err(_) => return None,
                },
                None => match record.get("_raw") {
                    Some(Value::Str(s)) => s.clone(),
                    _ => return None,
                },
            };

            let mut rec = Record::new();
            let mut pairs = Vec::new();
            let mut key = String::new();
            let mut val = String::new();
            let mut in_val = false;
            let mut in_quote = false;

            for ch in input_str.chars() {
                if !in_val {
                    if ch == '=' {
                        in_val = true;
                    } else if ch.is_whitespace() {
                        if !key.trim().is_empty() {
                            pairs.push((key.trim().to_string(), Value::Null));
                            key.clear();
                        }
                    } else {
                        key.push(ch);
                    }
                } else {
                    if ch == '"' {
                        in_quote = !in_quote;
                    } else if ch.is_whitespace() && !in_quote {
