                        } else if matched_str == "false" {
                            Value::Bool(false)
                        } else {
                            Value::Str(matched_str.to_string())
                        };
                        rec.set(var_name.clone(), val);
                    }
                }
                Some(rec)
            } else if *nodrop {
                let mut rec = record;
                for v in vars {
                    rec.set(v, Value::Null);
                }
                Some(rec)
            } else {
                None
            }
        }
        Operator::ParseRegex {
            regex,
            from,
            nodrop,
        } => {
            let input_str = match from {
                Some(f) => match record.get_path(f) {
                    Ok(v) => v.to_legacy_string(),
                    Err(_) => {
                        if *nodrop {
                            return Some(record);
                        } else {
                            return None;
                        }
                    }
                },
                None => match record.get("_raw") {
                    Some(Value::Str(s)) => s.clone(),
                    _ => return None,
                },
            };

            let re = match Regex::new(regex) {
                Ok(r) => r,
                Err(_) => return None,
            };

            if let Some(caps) = re.captures(&input_str) {
                let mut rec = record;
                for name in re.capture_names().flatten() {
                    if let Some(m) = caps.name(name) {
                        rec.set(name.to_string(), Value::Str(m.as_str().to_string()));
                    }
                }
                Some(rec)
            } else if *nodrop {
                Some(record)
            } else {
                None
            }
        }
        Operator::Fields { mode, fields } => {
            let mut rec = record;
            match mode {
                FieldsMode::Only => {
                    rec.fields.retain(|(k, _)| fields.contains(k));
                }
                FieldsMode::Except => {
                    rec.fields.retain(|(k, _)| !fields.contains(k));
                }
            }
            Some(rec)
        }
        Operator::Where { expr } => match expr.eval(&record) {
            Ok(v) if v.as_bool() => Some(record),
            _ => None,
        },
        Operator::Assignment { expr, name } => match expr.eval(&record) {
            Ok(val) => {
                let mut rec = record;
                rec.set(name, val);
                Some(rec)
            }
            Err(err) => {
                eprintln!("error: {}", err);
                None
            }
        },
        Operator::Timeslice {
            expr,
            duration,
            as_name,
        } => match expr.eval(&record) {
            Ok(Value::DateTime(dt)) => {
                let sliced_dt = truncate_datetime(dt, duration);
                let target_key = as_name.clone().unwrap_or_else(|| "_timeslice".to_string());
                let mut rec = record;
                rec.set(target_key, Value::DateTime(sliced_dt));
                Some(rec)
            }
            _ => None,
        },
        Operator::Total { expr, as_name } => match expr.eval(&record) {
            Ok(v) => {
                let n = v.as_f64().unwrap_or(0.0);
                *running_total += n;
                let target_key = as_name.clone().unwrap_or_else(|| "_total".to_string());
                let mut rec = record;
                rec.set(target_key, Value::Num(*running_total));
                Some(rec)
            }
            _ => None,
        },
        _ => Some(record),
    }
}

fn truncate_datetime(dt: DateTime<Utc>, duration_str: &str) -> DateTime<Utc> {
    let num_part: String = duration_str.chars().filter(|c| c.is_ascii_digit()).collect();
    let unit_part: String = duration_str.chars().filter(|c| c.is_ascii_alphabetic()).collect();

    let count: i64 = num_part.parse().unwrap_or(1);
    match unit_part.as_str() {
        "s" => dt.duration_trunc(Duration::seconds(count)).unwrap_or(dt),
        "m" => dt.duration_trunc(Duration::minutes(count)).unwrap_or(dt),
        "h" => dt.duration_trunc(Duration::hours(count)).unwrap_or(dt),
        "d" => dt.duration_trunc(Duration::days(count)).unwrap_or(dt),
        _ => dt,
    }
}
