    pub fn new(funcs: Vec<AggFunc>, by_exprs: Vec<Expr>) -> Self {
        AggregateState {
            funcs,
            by_exprs,
            groups: Vec::new(),
        }
    }

    pub fn process_record(&mut self, record: &Record) {
        let group_key: Vec<Value> = self
            .by_exprs
            .iter()
            .map(|e| e.eval(record).unwrap_or(Value::Null))
            .collect();

        let mut group_idx = None;
        for (idx, (k, _)) in self.groups.iter().enumerate() {
            if k == &group_key {
                group_idx = Some(idx);
                break;
            }
        }

        let idx = match group_idx {
            Some(i) => i,
            None => {
                let initial_accs = self
                    .funcs
                    .iter()
                    .map(|f| match f {
                        AggFunc::Count { .. } => Acc::Count(0),
                        AggFunc::Sum { .. } => Acc::Sum(0.0),
                        AggFunc::Min { .. } => Acc::Min(f64::MAX),
                        AggFunc::Max { .. } => Acc::Max(f64::MIN),
                        AggFunc::Average { .. } => Acc::Average { sum: 0.0, count: 0 },
                        AggFunc::Percentile { .. } => Acc::Percentile(Vec::new()),
                        AggFunc::CountDistinct { .. } => Acc::CountDistinct(HashSet::new()),
                    })
                    .collect();
                self.groups.push((group_key.clone(), initial_accs));
                self.groups.len() - 1
            }
        };

        let (_, accs) = &mut self.groups[idx];

        for (i, func) in self.funcs.iter().enumerate() {
            match func {
                AggFunc::Count { cond, .. } => {
                    let inc = match cond {
                        Some(c) => c.eval(record).map(|v| v.as_bool()).unwrap_or(false),
                        None => true,
                    };
                    if inc {
                        if let Acc::Count(ref mut c) = accs[i] {
                            *c += 1;
                        }
                    }
                }
                AggFunc::Sum { expr, .. } => {
                    if let Ok(v) = expr.eval(record) {
                        if let Some(n) = v.as_f64() {
                            if let Acc::Sum(ref mut s) = accs[i] {
                                *s += n;
                            }
                        }
                    }
                }
                AggFunc::Min { expr, .. } => {
                    if let Ok(v) = expr.eval(record) {
                        if let Some(n) = v.as_f64() {
                            if let Acc::Min(ref mut m) = accs[i] {
                                *m = (*m).min(n);
                            }
                        }
                    }
                }
                AggFunc::Max { expr, .. } => {
                    if let Ok(v) = expr.eval(record) {
                        if let Some(n) = v.as_f64() {
                            if let Acc::Max(ref mut m) = accs[i] {
                                *m = (*m).max(n);
                            }
                        }
                    }
                }
                AggFunc::Average { expr, .. } => {
                    if let Ok(v) = expr.eval(record) {
                        if let Some(n) = v.as_f64() {
                            if let Acc::Average { ref mut sum, ref mut count } = accs[i] {
                                *sum += n;
                                *count += 1;
                            }
                        }
                    }
                }
                AggFunc::Percentile { expr, .. } => {
                    if let Ok(v) = expr.eval(record) {
                        if let Some(n) = v.as_f64() {
                            if let Acc::Percentile(ref mut pvec) = accs[i] {
                                pvec.push(n);
                            }
                        }
                    }
                }
                AggFunc::CountDistinct { expr, .. } => {
                    if let Ok(v) = expr.eval(record) {
                        let repr = v.to_legacy_string();
                        if let Acc::CountDistinct(ref mut set) = accs[i] {
                            set.insert(repr);
                        }
                    }
                }
            }
        }
    }

    pub fn finish(self) -> Vec<Record> {
        let mut results = Vec::new();

        for (group_key, accs) in self.groups {
            let mut rec = Record::new();

            // Set group key fields first
            for (i, by_expr) in self.by_exprs.iter().enumerate() {
                let key_name = match by_expr {
                    Expr::Var(v) => v.clone(),
                    _ => by_expr.to_string(),
                };
                let val = group_key.get(i).cloned().unwrap_or(Value::Null);
                rec.set(key_name, val);
            }

            // Set aggregate results
            for (i, func) in self.funcs.iter().enumerate() {
                let col_name = func.default_name();
                let val = match (&func, &accs[i]) {
                    (_, Acc::Count(c)) => Value::Num(*c as f64),
                    (_, Acc::Sum(s)) => Value::Num(*s),
                    (_, Acc::Min(m)) => {
                        if *m == f64::MAX {
                            Value::Null
                        } else {
                            Value::Num(*m)
                        }
                    }
                    (_, Acc::Max(m)) => {
                        if *m == f64::MIN {
                            Value::Null
                        } else {
                            Value::Num(*m)
                        }
                    }
                    (_, Acc::Average { sum, count }) => {
                        if *count == 0 {
                            Value::Null
                        } else {
                            Value::Num(*sum / (*count as f64))
                        }
                    }
                    (AggFunc::Percentile { pct, .. }, Acc::Percentile(pvec)) => {
                        if pvec.is_empty() {
                            Value::Null
                        } else {
                            let mut sorted = pvec.clone();
                            sorted.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
                            let n = sorted.len();
                            let idx = (((*pct as f64) / 100.0) * (n as f64)).ceil() as usize;
                            let final_idx = idx.saturating_sub(1).min(n - 1);
                            Value::Num(sorted[final_idx])
                        }
                    }
                    (_, Acc::CountDistinct(set)) => Value::Num(set.len() as f64),
                    _ => Value::Null,
                };
                rec.set(col_name, val);
            }

            results.push(rec);
        }

        results
    }
}
