use crate::parser::expr::Expr;
use crate::parser::operator::SortDir;
use crate::record::Record;
use std::cmp::Ordering;

pub fn sort_records(records: &mut [Record], items: &[(Expr, SortDir)]) {
    records.sort_by(|a, b| {
        for (expr, dir) in items {
            let val_a = expr.eval(a).ok();
            let val_b = expr.eval(b).ok();

            let cmp = match (val_a, val_b) {
                (Some(va), Some(vb)) => va.partial_cmp(&vb).unwrap_or(Ordering::Equal),
                (Some(_), None) => Ordering::Greater,
                (None, Some(_)) => Ordering::Less,
                (None, None) => Ordering::Equal,
            };

            if cmp != Ordering::Equal {
                return if *dir == SortDir::Desc {
                    cmp.reverse()
                } else {
                    cmp
                };
            }
        }
        Ordering::Equal
    });
}
EOF

