    let alias_dir_path = cli.alias_dir.as_ref().map(Path::new);
    let alias_mgr = match AliasManager::load(alias_dir_path, cli.no_alias) {
        Ok(mgr) => mgr,
        Err(err) => {
            eprintln!("{}", err);
            exit(1);
        }
    };

    let expanded_query = alias_mgr.expand(&raw_query);

    let query = match parse_query(&expanded_query) {
        Ok(q) => q,
        Err(err) => {
            eprintln!("{}", err);
            eprintln!("Error: Failed to parse query");
            exit(1);
        }
    };

    let output_arg = cli.output.as_deref().unwrap_or("legacy");
    let (output_mode, fmt_opt) = if let Some(m_fmt) = cli.format {
        (OutputMode::Format, Some(m_fmt))
    } else {
        match OutputMode::parse(output_arg) {
            Ok(res) => res,
            Err(err) => {
                eprintln!("{}", err);
                exit(1);
            }
        }
    };

    let lines: Box<dyn Iterator<Item = String>> = if let Some(file_path) = &cli.file {
        let file = match File::open(file_path) {
            Ok(f) => f,
            Err(err) => {
                eprintln!("Error: Os {{ code: {}, kind: {:?}, message: \"{}\" }}", err.raw_os_error().unwrap_or(2), err.kind(), err);
                exit(1);
            }
        };
        let reader = BufReader::new(file);
        Box::new(reader.lines().filter_map(Result::ok))
    } else {
        let stdin = io::stdin();
        let reader = stdin.lock();
        Box::new(reader.lines().filter_map(Result::ok))
    };

    execute_pipeline(lines, query, output_mode, fmt_opt);
}
EOF"}

