use crate::engine::aggregators::AggregateState;
use crate::engine::operators::execute_non_aggregate_operator;
use crate::engine::sorter::sort_records;
use crate::parser::operator::Operator;
use crate::parser::Query;
use crate::record::Record;
use crate::render::aggregate::AggregateRenderer;
use crate::render::non_aggregate::NonAggregateRenderer;
use crate::render::OutputMode;

pub fn execute_pipeline<I>(
    lines: I,
    query: Query,
    output_mode: OutputMode,
    format_str: Option<String>,
) where
    I: Iterator<Item = String>,
{
    // Check if query contains any aggregate or sort operators
    let has_aggregate = query.operators.iter().any(|op| matches!(op, Operator::Aggregate { .. }));
    let has_sort = query.operators.iter().any(|op| matches!(op, Operator::Sort { .. }));
    let has_negative_limit = query.operators.iter().any(|op| match op {
        Operator::Limit { count } => *count < 0,
        _ => false,
    });

    let mut running_total = 0.0;

    if !has_aggregate && !has_sort && !has_negative_limit {
        // Pure streaming mode
        let mut non_agg_renderer = NonAggregateRenderer::new(output_mode, format_str);
        let mut processed_count = 0i64;

        'outer: for line in lines {
            if !query.filter.matches(&line) {
                continue;
            }

            let mut current_record = Record::from_raw(line);

            for op in &query.operators {
                match op {
                    Operator::Limit { count } => {
                        if *count > 0 && processed_count >= *count {
                            break 'outer;
                        }
                    }
                    _ => {
                        if let Some(next_rec) = execute_non_aggregate_operator(op, current_record, &mut running_total) {
                            current_record = next_rec;
                        } else {
                            continue 'outer;
                        }
                    }
                }
            }

            processed_count += 1;
            non_agg_renderer.render_record(&current_record);
        }
    } else {
        // Buffered / Aggregate mode
        let mut buffered_records: Vec<Record> = Vec::new();
        let mut agg_state: Option<AggregateState> = None;
        let mut agg_op_idx = None;

        for (idx, op) in query.operators.iter().enumerate() {
            if let Operator::Aggregate { funcs, by } = op {
                agg_state = Some(AggregateState::new(funcs.clone(), by.clone()));
                agg_op_idx = Some(idx);
                break;
            }
        }

        let first_phase_ops = if let Some(idx) = agg_op_idx {
            &query.operators[..idx]
        } else {
            &query.operators[..]
        };

        for line in lines {
            if !query.filter.matches(&line) {
                continue;
            }

            let mut current_record = Some(Record::from_raw(line));

            for op in first_phase_ops {
                if let Some(rec) = current_record {
                    current_record = execute_non_aggregate_operator(op, rec, &mut running_total);
                } else {
                    break;
                }
            }

            if let Some(rec) = current_record {
                if let Some(state) = &mut agg_state {
                    state.process_record(&rec);
                } else {
                    buffered_records.push(rec);
                }
            }
        }

        let mut final_records = if let Some(state) = agg_state {
            state.finish()
        } else {
            buffered_records
        };

        let second_phase_ops = if let Some(idx) = agg_op_idx {
            &query.operators[idx + 1..]
        } else {
            &[]
        };

        for op in second_phase_ops {
            match op {
                Operator::Sort { items } => {
                    sort_records(&mut final_records, items);
                }
                Operator::Limit { count } => {
                    if *count > 0 {
                        final_records.truncate(*count as usize);
                    } else if *count < 0 {
                        let len = final_records.len();
                        let keep = (-*count) as usize;
                        if len > keep {
                            final_records = final_records[len - keep..].to_vec();
                        }
                    }
                }
                _ => {
                    let mut next_records = Vec::new();
                    for rec in final_records {
                        if let Some(r) = execute_non_aggregate_operator(op, rec, &mut running_total) {
                            next_records.push(r);
                        }
                    }
                    final_records = next_records;
                }
            }
        }

        let agg_renderer = AggregateRenderer::new(output_mode, format_str);
        agg_renderer.render_table(&final_records);
    }
}
EOF"}

