            } else if arg == "-o" || arg == "--output" {
                if i + 1 < args.len() {
                    output = Some(args[i + 1].clone());
                    i += 1;
                }
            } else if arg.starts_with("-o=") || arg.starts_with("--output=") {
                let eq_idx = arg.find('=').unwrap();
                output = Some(arg[eq_idx + 1..].to_string());
