    Add,
    Sub,
    Mul,
    Div,
    Eq,
    Neq,
    Lt,
    Lte,
    Gt,
    Gte,
    And,
    Or,
}

#[derive(Debug, Clone, PartialEq)]
pub enum UnaryOp {
    Not,
    Neg,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Expr {
    Lit(Value),
    Var(String),
    Unary {
        op: UnaryOp,
        expr: Box<Expr>,
    },
    Binary {
        op: BinaryOp,
        left: Box<Expr>,
        right: Box<Expr>,
    },
    Call {
        name: String,
        args: Vec<Expr>,
    },
}

impl fmt::Display for Expr {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Expr::Lit(v) => write!(f, "{}", v),
            Expr::Var(s) => write!(f, "{}", s),
            Expr::Unary { op, expr } => match op {
                UnaryOp::Not => write!(f, "!{}", expr),
                UnaryOp::Neg => write!(f, "-{}", expr),
            },
            Expr::Binary { op, left, right } => {
                let op_str = match op {
                    BinaryOp::Add => "+",
                    BinaryOp::Sub => "-",
                    BinaryOp::Mul => "*",
                    BinaryOp::Div => "/",
                    BinaryOp::Eq => "==",
                    BinaryOp::Neq => "!=",
                    BinaryOp::Lt => "<",
                    BinaryOp::Lte => "<=",
                    BinaryOp::Gt => ">",
                    BinaryOp::Gte => ">=",
                    BinaryOp::And => "and",
                    BinaryOp::Or => "or",
                };
                write!(f, "{} {} {}", left, op_str, right)
            }
            Expr::Call { name, args } => {
                let arg_strs: Vec<String> = args.iter().map(|a| a.to_string()).collect();
                write!(f, "{}({})", name, arg_strs.join(", "))
            }
        }
    }
}

impl Expr {
    pub fn eval(&self, record: &Record) -> Result<Value, String> {
        match self {
            Expr::Lit(v) => Ok(v.clone()),
            Expr::Var(var_name) => record.get_path(var_name),
            Expr::Unary { op, expr } => {
                let val = expr.eval(record)?;
                match op {
                    UnaryOp::Not => Ok(Value::Bool(!val.as_bool())),
                    UnaryOp::Neg => {
                        let n = val
                            .as_f64()
                            .ok_or_else(|| format!("Expected numeric operand for '-'"))?;
                        Ok(Value::Num(-n))
                    }
                }
            }
            Expr::Binary { op, left, right } => {
                if *op == BinaryOp::And {
                    let l_val = left.eval(record)?;
                    if !l_val.as_bool() {
                        return Ok(Value::Bool(false));
                    }
                    let r_val = right.eval(record)?;
                    return Ok(Value::Bool(r_val.as_bool()));
                }
                if *op == BinaryOp::Or {
                    let l_val = left.eval(record)?;
                    if l_val.as_bool() {
                        return Ok(Value::Bool(true));
                    }
                    let r_val = right.eval(record)?;
                    return Ok(Value::Bool(r_val.as_bool()));
                }

                let l_val = left.eval(record)?;
                let r_val = right.eval(record)?;

                match op {
                    BinaryOp::Eq => Ok(Value::Bool(l_val == r_val)),
                    BinaryOp::Neq => Ok(Value::Bool(l_val != r_val)),
                    BinaryOp::Lt => Ok(Value::Bool(l_val < r_val)),
                    BinaryOp::Lte => Ok(Value::Bool(l_val <= r_val)),
                    BinaryOp::Gt => Ok(Value::Bool(l_val > r_val)),
                    BinaryOp::Gte => Ok(Value::Bool(l_val >= r_val)),
                    BinaryOp::Add => {
                        let l_num = l_val.as_f64();
                        let r_num = r_val.as_f64();
                        if let (Some(l), Some(r)) = (l_num, r_num) {
                            Ok(Value::Num(l + r))
                        } else {
                            Err(format!("Expected numeric operands, found {} + {}", l_val, r_val))
                        }
                    }
                    BinaryOp::Sub => {
                        let l_num = l_val.as_f64();
                        let r_num = r_val.as_f64();
                        if let (Some(l), Some(r)) = (l_num, r_num) {
                            Ok(Value::Num(l - r))
                        } else {
                            Err(format!("Expected numeric operands for '-'"))
                        }
                    }
                    BinaryOp::Mul => {
                        let l_num = l_val.as_f64();
                        let r_num = r_val.as_f64();
                        if let (Some(l), Some(r)) = (l_num, r_num) {
                            Ok(Value::Num(l * r))
                        } else {
                            Err(format!("Expected numeric operands for '*'"))
                        }
                    }
                    BinaryOp::Div => {
                        let l_num = l_val.as_f64();
                        let r_num = r_val.as_f64();
                        if let (Some(l), Some(r)) = (l_num, r_num) {
                            Ok(Value::Num(l / r))
                        } else {
                            Err(format!("Expected numeric operands for '/'"))
                        }
                    }
                    _ => unreachable!(),
                }
            }
            Expr::Call { name, args } => eval_func(name, args, record),
        }
    }
}

fn eval_func(name: &str, args: &[Expr], record: &Record) -> Result<Value, String> {
    match name {
        "abs" => {
            let val = args
                .get(0)
                .ok_or_else(|| "abs requires 1 argument".to_string())?
                .eval(record)?;
            let n = val.as_f64().ok_or_else(|| "abs expected number".to_string())?;
            Ok(Value::Num(n.abs()))
        }
        "ceil" => {
            let val = args
                .get(0)
                .ok_or_else(|| "ceil requires 1 argument".to_string())?
                .eval(record)?;
            let n = val.as_f64().ok_or_else(|| "ceil expected number".to_string())?;
            Ok(Value::Num(n.ceil()))
        }
        "floor" => {
            let val = args
                .get(0)
                .ok_or_else(|| "floor requires 1 argument".to_string())?
                .eval(record)?;
            let n = val.as_f64().ok_or_else(|| "floor expected number".to_string())?;
            Ok(Value::Num(n.floor()))
        }
        "round" => {
            let val = args
                .get(0)
                .ok_or_else(|| "round requires 1 argument".to_string())?
                .eval(record)?;
            let n = val.as_f64().ok_or_else(|| "round expected number".to_string())?;
            Ok(Value::Num(n.round()))
        }
        "sqrt" => {
            let val = args
                .get(0)
                .ok_or_else(|| "sqrt requires 1 argument".to_string())?
                .eval(record)?;
            let n = val.as_f64().ok_or_else(|| "sqrt expected number".to_string())?;
            Ok(Value::Num(n.sqrt()))
        }
        "concat" => {
            let mut res = String::new();
            for arg in args {
                let v = arg.eval(record)?;
                res.push_str(&v.to_legacy_string());
            }
            Ok(Value::Str(res))
        }
        "contains" => {
            let haystack = args
                .get(0)
                .ok_or_else(|| "contains requires 2 args".to_string())?
                .eval(record)?;
            let needle = args
                .get(1)
                .ok_or_else(|| "contains requires 2 args".to_string())?
                .eval(record)?;
            Ok(Value::Bool(
                haystack.to_legacy_string().contains(&needle.to_legacy_string()),
            ))
        }
        "length" => {
            let val = args
                .get(0)
                .ok_or_else(|| "length requires 1 argument".to_string())?
                .eval(record)?;
            Ok(Value::Num(val.to_legacy_string().chars().count() as f64))
        }
        "now" => Ok(Value::DateTime(Utc::now())),
        "num" => {
            let val = args
                .get(0)
                .ok_or_else(|| "num requires 1 argument".to_string())?
                .eval(record)?;
            let n = val
                .as_f64()
                .ok_or_else(|| format!("Cannot convert {} to number", val))?;
            Ok(Value::Num(n))
        }
        "parseDate" => {
            let val = args
                .get(0)
                .ok_or_else(|| "parseDate requires 1 argument".to_string())?
                .eval(record)?;
            let s = val.to_legacy_string();
            let dt = DateTime::parse_from_rfc3339(&s)
                .map(|d| d.with_timezone(&Utc))
                .or_else(|_| {
                    DateTime::parse_from_str(&s, "%Y-%m-%d %H:%M:%S %z")
                        .map(|d| d.with_timezone(&Utc))
                })
                .or_else(|_| {
                    NaiveDateTime::parse_from_str(&s, "%Y-%m-%d %H:%M:%S")
                        .map(|d| d.and_utc())
                })
                .or_else(|_| {
                    NaiveDateTime::parse_from_str(&s, "%Y-%m-%dT%H:%M:%SZ")
                        .map(|d| d.and_utc())
                })
                .or_else(|_| {
                    NaiveDateTime::parse_from_str(&s, "%Y-%m-%dT%H:%M:%S.%fZ")
                        .map(|d| d.and_utc())
                })
                .map_err(|err| {
                    format!("The 'parseDate' function failed with the error: {:?}", err)
                })?;
            Ok(Value::DateTime(dt))
        }
        "parseHex" => {
            let val = args
                .get(0)
                .ok_or_else(|| "parseHex requires 1 argument".to_string())?
                .eval(record)?;
            let s = val.to_legacy_string();
            let clean = s.trim_start_matches("0x");
            let n = u64::from_str_radix(clean, 16)
                .map_err(|_| format!("Invalid hex string \"{}\"", s))?;
            Ok(Value::Num(n as f64))
        }
        "substring" => {
            let val = args
                .get(0)
                .ok_or_else(|| "substring requires at least 2 args".to_string())?
                .eval(record)?;
            let s = val.to_legacy_string();
            let start = args
                .get(1)
                .ok_or_else(|| "substring start".to_string())?
                .eval(record)?
                .as_f64()
                .ok_or_else(|| "substring start must be number".to_string())? as usize;
            let end = if let Some(e) = args.get(2) {
                e.eval(record)?
                    .as_f64()
                    .ok_or_else(|| "substring end must be number".to_string())? as usize
            } else {
                s.chars().count()
            };
            let chars: Vec<char> = s.chars().collect();
            let sub: String = chars
                .into_iter()
                .skip(start)
                .take(end.saturating_sub(start))
                .collect();
            Ok(Value::Str(sub))
        }
        "toLowerCase" => {
            let val = args
                .get(0)
                .ok_or_else(|| "toLowerCase requires 1 arg".to_string())?
                .eval(record)?;
            Ok(Value::Str(val.to_legacy_string().to_lowercase()))
        }
        "toUpperCase" => {
            let val = args
                .get(0)
                .ok_or_else(|| "toUpperCase requires 1 arg".to_string())?
                .eval(record)?;
            Ok(Value::Str(val.to_legacy_string().to_uppercase()))
        }
        "isNull" => {
            let val = match args.get(0) {
                Some(arg) => match arg.eval(record) {
                    Ok(v) => v,
                    Err(_) => Value::Null,
                },
                None => Value::Null,
            };
            Ok(Value::Bool(val == Value::Null))
        }
        "isEmpty" => {
            let val = match args.get(0) {
                Some(arg) => match arg.eval(record) {
                    Ok(v) => v,
                    Err(_) => Value::Null,
                },
                None => Value::Null,
            };
            let is_emp = match val {
                Value::Null => true,
                Value::Str(s) => s.is_empty(),
                _ => false,
            };
            Ok(Value::Bool(is_emp))
        }
        "isBlank" => {
            let val = match args.get(0) {
                Some(arg) => match arg.eval(record) {
                    Ok(v) => v,
                    Err(_) => Value::Null,
                },
                None => Value::Null,
            };
            let is_blk = match val {
                Value::Null => true,
                Value::Str(s) => s.trim().is_empty(),
                _ => false,
            };
            Ok(Value::Bool(is_blk))
        }
        "isNumeric" => {
            let val = match args.get(0) {
                Some(arg) => match arg.eval(record) {
                    Ok(v) => v,
                    Err(_) => Value::Null,
                },
                None => Value::Null,
            };
            let is_num = val.as_f64().is_some();
            Ok(Value::Bool(is_num))
        }
        "if" => {
            let cond = args
                .get(0)
                .ok_or_else(|| "if requires 3 arguments".to_string())?
                .eval(record)?;
            if cond.as_bool() {
                args.get(1)
                    .ok_or_else(|| "if requires 3 arguments".to_string())?
                    .eval(record)
            } else {
                args.get(2)
                    .ok_or_else(|| "if requires 3 arguments".to_string())?
                    .eval(record)
            }
        }
        _ => Err(format!("Unknown function {}", name)),
    }
}
EOF"}

