                .ok_or_else(|| "ceil requires 1 argument".to_string())?
                .eval(record)?;
            let n = val.as_f64().ok_or_else(|| "ceil expected number".to_string())?;
            Ok(Value::Num(n.ceil()))
        }
        "floor" => {
            let val = args
                .get(0)
                .ok_or_else(|| "floor requires 1 argument".to_string())?
                .eval(record)?;
            let n = val.as_f64().ok_or_else(|| "floor expected number".to_string())?;
            Ok(Value::Num(n.floor()))
        }
        "round" => {
            let val = args
                .get(0)
                .ok_or_else(|| "round requires 1 argument".to_string())?
                .eval(record)?;
            let n = val.as_f64().ok_or_else(|| "round expected number".to_string())?;
            Ok(Value::Num(n.round()))
        }
        "sqrt" => {
            let val = args
                .get(0)
                .ok_or_else(|| "sqrt requires 1 argument".to_string())?
                .eval(record)?;
            let n = val.as_f64().ok_or_else(|| "sqrt expected number".to_string())?;
            Ok(Value::Num(n.sqrt()))
