                        .map(|d| d.and_utc())
                })
                .or_else(|_| {
                    NaiveDateTime::parse_from_str(&s, "%Y-%m-%dT%H:%M:%S.%fZ")
                        .map(|d| d.and_utc())
                })
                .map_err(|err| {
