fn find_matching_paren(s: &str, start_idx: usize) -> Option<usize> {
    let mut depth = 0;
    for (i, ch) in s[start_idx..].char_indices() {
        if ch == '(' {
            depth += 1;
        } else if ch == ')' {
            depth -= 1;
            if depth == 0 {
                return Some(start_idx + i);
            }
        }
    }
    None
}
