fn parse_timeslice_op(s: &str) -> Result<Operator, String> {
    let rest = s["timeslice".len()..].trim();
    let open_p = rest.find('(').ok_or_else(|| "timeslice missing '('".to_string())?;
    let close_p = find_matching_paren(rest, open_p).ok_or_else(|| "timeslice missing ')'".to_string())?;
    let expr_str = rest[open_p + 1..close_p].trim();
    let expr = parse_expr(expr_str)?;

    let after = rest[close_p + 1..].trim();
    let mut parts = after.split_whitespace();
    let duration = parts.next().unwrap_or("1m").to_string();

